// Complete Demonstration: Event Propagation & Event Delegation
const parent = document.querySelector("#parent");
const child = document.querySelector("#child");

// 1. Capturing Phase listener (Third argument: { capture: true })
parent.addEventListener("click", (event) => {
  console.log("[1. Capturing] Parent intercepted event | target:", event.target.id);
}, { capture: true });

// 2. Target Phase listener
child.addEventListener("click", (event) => {
  console.log("[2. Target Phase] Button clicked | target:", event.target.id, "| currentTarget:", event.currentTarget.id);
  // event.stopPropagation(); // Uncomment to halt bubbling to parent
});

// 3. Bubbling Phase listener (Default behavior)
parent.addEventListener("click", (event) => {
  console.log("[3. Bubbling Phase] Parent handled event | target:", event.target.id, "| currentTarget:", event.currentTarget.id);
});

// 4. Practical Event Delegation Pattern
const list = document.querySelector("#todo-list");
list.addEventListener("click", (event) => {
  if (event.target.matches("button.delete-btn")) {
    const listItem = event.target.closest("li");
    console.log("Deleted item:", listItem.dataset.id);
    listItem.remove();
  }
});

